import React, { Component } from 'react';
import './googlemap.css';

class GoogleMapComponent extends Component {
    componentDidMount() {
        const { location } = this.props;
        const { lat, lng } = location?.state || {};

        const initMap = () => {
            const defaultLocation = { lat: 0, lng: 0 };
            const mapLocation = lat && lng ? { lat, lng } : defaultLocation;

            const map = new window.google.maps.Map(document.getElementById('map'), {
                zoom: 12,
                center: mapLocation,
            });

            const directionsService = new window.google.maps.DirectionsService();
            const directionsRenderer = new window.google.maps.DirectionsRenderer();
            directionsRenderer.setMap(map);

            const calculateAndDisplayRoute = (start, end) => {
                directionsService.route(
                    {
                        origin: start,
                        destination: end,
                        travelMode: 'DRIVING',
                    },
                    (response, status) => {
                        if (status === 'OK') {
                            directionsRenderer.setDirections(response);
                        } else {
                            console.error('Directions request failed due to ' + status);
                        }
                    }
                );
            };

            if (lat && lng) {
                if (navigator.geolocation) {
                    navigator.geolocation.getCurrentPosition(
                        (position) => {
                            const start = {
                                lat: position.coords.latitude,
                                lng: position.coords.longitude,
                            };
                            const end = { lat, lng };
                            calculateAndDisplayRoute(start, end);

                            new window.google.maps.marker.AdvancedMarkerElement({
                                position: start,
                                map: map,
                                title: 'Your Location',
                            });

                            new window.google.maps.marker.AdvancedMarkerElement({
                                position: end,
                                map: map,
                                title: 'Destination',
                            });
                        },
                        (error) => {
                            console.error('Error fetching current position', error);
                        }
                    );
                } else {
                    console.error('Geolocation not supported');
                }
            }
        };

        const loadScript = (url) => {
            return new Promise((resolve, reject) => {
                const script = document.createElement('script');
                script.src = url;
                script.async = true;
                script.defer = true;
                script.onload = resolve;
                script.onerror = reject;
                document.head.appendChild(script);
            });
        };

        if (!window.google || !window.google.maps) {
            window.initMap = initMap;
            loadScript(`https://maps.googleapis.com/maps/api/js?key=AIzaSyAyCujJ188OdhtBjKLmV2CheQgDnqEa-9o&callback=initMap`)
                .then(() => {
                    console.log('Google Maps API loaded successfully');
                })
                .catch((error) => {
                    console.error('Error loading Google Maps API script:', error);
                });

            return () => {
                delete window.initMap;
            };
        } else {
            initMap();
        }
    }

    render() {
        return (
            <div className="container">
                <div id="map" style={{ height: '400px', width: '100%' }}></div>
            </div>
        );
    }
}

export default GoogleMapComponent;
